#!/usr/bin/env bash
# SwiftUI Enhancement Acceptance Probes — HARD GATE.
#
# Invoked by `enhance-policy-swiftui` SKILL.md after all enhancement writes.
# Run from the SwiftUI project root (the directory that contains `Features/`,
# `DesignSystem/`, `Colors.xcassets/`, the `@main` App file, etc.).
#
# DO NOT edit this script's echo strings to invent non-FAIL exit codes. Every
# `FAIL:` line is real work that the enhance agent must resolve by re-entering
# Step 5. Any `OK:..._NOT_REQUIRED`-style additions are a self-skip.

set +e

fail_count=0
warn_count=0

emit_ok()   { echo "OK:$1"; }
emit_fail() { echo "FAIL:$1"; fail_count=$((fail_count+1)); }
emit_warn() { echo "WARN:$1"; warn_count=$((warn_count+1)); }

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
EXPECTED_FIGMA_PROBE="$SCRIPT_DIR/verify_figma_components.cjs"
if [ ! -f "$EXPECTED_FIGMA_PROBE" ]; then
  EXPECTED_FIGMA_PROBE="$SCRIPT_DIR/../../enhance-execute/references/verify_figma_components.cjs"
fi

swift_sources() {
  find . -name '*.swift' \
    -not -path '*/.locofy/*' -not -path '*generated*' \
    -not -path '*/DerivedData/*' -not -path '*/build/*' 2>/dev/null | sed 's#^\./##' | sort -u
}

feature_name_from_view() {
  echo "$1" | sed -E 's#^Features/([^/]+)/Views/.*#\1#'
}

is_placeholder_view() {
  f="$1"
  [ -f "$f" ] || return 1
  line_count=$(grep -vcE '^[[:space:]]*$|^[[:space:]]*//|#Preview|PreviewProvider' "$f" 2>/dev/null)
  [ "$line_count" -le 18 ] || return 1
  grep -qE '\bText\(' "$f" || return 1
  grep -qE '\b(Image|AsyncImage|Button|List|ScrollView|LazyV|LazyH|ForEach|NavigationStack|NavigationLink|BottomNavigationView|[A-Z][A-Za-z0-9_]+View\()' "$f" && return 1
  return 0
}

production_ref_count() {
  name="$1"
  own="$2"
  count=0
  while IFS= read -r hit; do
    [ -z "$hit" ] && continue
    file=${hit%%:*}
    line=${hit#*:}
    [ "$file" = "$own" ] && continue
    echo "$line" | grep -qE '#Preview|PreviewProvider|preview|Preview' && continue
    count=$((count+1))
  done < <(grep -rnE "\b$name\b" $(swift_sources) 2>/dev/null)
  echo "$count"
}

GENERATED_GROUPS=""
for candidate in \
  .locofy/agent/memory/generated-component-groups.md \
  ../.locofy/agent/memory/generated-component-groups.md \
  ../../.locofy/agent/memory/generated-component-groups.md; do
  if [ -f "$candidate" ]; then
    GENERATED_GROUPS="$candidate"
    break
  fi
done

generated_group_rows() {
  [ -n "$GENERATED_GROUPS" ] || return
  awk -F'|' '
    function trim(s) {
      gsub(/^[[:space:]]+|[[:space:]]+$/, "", s)
      gsub(/`/, "", s)
      return s
    }
    {
      header=trim($2)
      if (header == "Raw generated names/files") { in_table=1; next }
      if (!in_table || $0 !~ /^\|/) next
      raw=trim($2)
      key=trim($3)
      existing=trim($4)
      canonical=trim($5)
      if (raw == "" || raw ~ /^-+$/) next
      printf "%s\t%s\t%s\t%s\n", raw, key, existing, canonical
    }
  ' "$GENERATED_GROUPS"
}

canonical_type_from_cell() {
  printf '%s\n' "$1" | sed -E 's#[[:space:]]*/[[:space:]].*$##; s#^[[:space:]]+|[[:space:]]+$##g'
}

canonical_path_from_cell() {
  printf '%s\n' "$1" | sed -E 's#^[^/]*/[[:space:]]*##; s#^[[:space:]]+|[[:space:]]+$##g'
}

resolve_generated_canonical_file() {
  wanted="$1"
  for candidate in "$wanted" "../$wanted" "../../$wanted"; do
    if [ -f "$candidate" ]; then
      printf '%s\n' "$candidate" | sed 's#^\./##'
      return
    fi
  done
  base=$(basename "$wanted")
  find . .. ../.. -type f -name "$base" \
    -not -path '*/.locofy/*' -not -path '*generated*' \
    -not -path '*/DerivedData/*' -not -path '*/build/*' 2>/dev/null \
    | head -1 | sed 's#^\./##'
}

has_pascal_case_component_path() {
  local checked_path checked_folder checked_file
  checked_path=${1#./}
  case "$checked_path" in
    UIComponents/*) checked_path=${checked_path#UIComponents/} ;;
    */UIComponents/*) checked_path=${checked_path#*UIComponents/} ;;
    *) return 1 ;;
  esac
  checked_folder=${checked_path%%/*}
  checked_file=${checked_path#*/}
  [ "$checked_folder" != "$checked_path" ] || return 1
  case "$checked_file" in */*) return 1;; esac
  printf '%s\n' "$checked_folder" | grep -qE '^[A-Z][A-Za-z0-9]*$' || return 1
  printf '%s\n' "$checked_file" | grep -qE '\.swift$'
}

has_navigation_component_path() {
  local checked_path checked_folder checked_file expected_folder
  has_pascal_case_component_path "$1" || return 1
  checked_path=${1#./}
  checked_path=${checked_path#*UIComponents/}
  checked_folder=${checked_path%%/*}
  checked_file=${checked_path#*/}
  expected_folder=${checked_file%.swift}
  expected_folder=${expected_folder%View}
  [ "$checked_folder" = "$expected_folder" ]
}

############################
# A. Localization — canonical API is `enum Localization: String` + `.localized`
#    (NSLocalizedString-backed). GREENFIELD must CREATE this system; CONFORM
#    extends the project's EXISTING one. `LocalizedStringKey`/`LocalizationKeys`
#    are BANNED (full canonical swap to NSLocalizedString `.localized`).
############################
# The localization system is present when a `.localized` accessor exists
# (e.g. `enum Localization: String { } + var localized: String { NSLocalizedString(rawValue, ...) }`).
LOC_SYS=0
if grep -rqsE 'var localized: String|func localized\(' --include='*.swift' . 2>/dev/null; then
  LOC_SYS=1
fi
if [ "$LOC_SYS" -eq 1 ]; then emit_ok LOCALIZATION_SYSTEM; else emit_fail LOCALIZATION_SYSTEM_MISSING; fi

# Raw English Text("Capitalized") literals are banned — every user-visible
# string must route through `Localization.<case>.localized`. Only dynamic data
# may use `Text(verbatim: ...)`.
text_lit=$(grep -rnE 'Text\("[A-Za-z][^"]*"\)' Features Views UIComponents 2>/dev/null | grep -cv 'verbatim:')
if [ "$text_lit" -eq 0 ]; then emit_ok TEXT_LITERALS; else
  emit_fail "TEXT_LITERALS=$text_lit"
  grep -rnE 'Text\("[A-Za-z][^"]*"\)' Features Views UIComponents 2>/dev/null | grep -v 'verbatim:' | head -10
fi

a11y_lit=$(grep -rcE 'accessibilityCommon\([^)]*label:\s*"[^"]' Features Views UIComponents 2>/dev/null | awk -F: '{s+=$2} END{print s+0}')
if [ "$a11y_lit" -eq 0 ]; then emit_ok A11Y_LABEL_LITERALS; else emit_fail "A11Y_LABEL_LITERALS=$a11y_lit"; fi

# A2. NO_LOCALIZEDSTRINGKEY (#1) — full canonical swap: `LocalizedStringKey(` and
# `LocalizationKeys.` are banned in views. Every user-visible string goes through
# the `.localized` enum accessor instead. Mixing the two APIs is the "mixed use" bug.
lsk=$(grep -rcE 'LocalizedStringKey\(|LocalizationKeys\.' Features Views UIComponents 2>/dev/null | awk -F: '{s+=$2} END{print s+0}')
if [ "$lsk" -eq 0 ]; then emit_ok NO_LOCALIZEDSTRINGKEY; else
  emit_fail "LOCALIZEDSTRINGKEY_IN_VIEWS=$lsk"
  grep -rnE 'LocalizedStringKey\(|LocalizationKeys\.' Features Views UIComponents 2>/dev/null | head -5
fi

# A3. CATALOG + ORPHAN keys (#2) — every `Localization.<case>` referenced in views
# must resolve to a real VALUE in the strings catalog (the case rawValue is the
# key). A case absent from the catalog renders the raw key string on screen.
CATALOG=$(find . -name 'Localizable.xcstrings' 2>/dev/null | head -1)
if [ "$LOC_SYS" -eq 1 ]; then
  if [ -z "$CATALOG" ]; then
    emit_fail LOC_CATALOG_MISSING
  else
    emit_ok LOC_CATALOG_PRESENT
    # Extract every Localization case used in views (rawValue == case name) and
    # confirm each appears as a key in the catalog.
    used=$(grep -rhoE 'Localization\.[A-Za-z][A-Za-z0-9_]*' Features Views UIComponents 2>/dev/null | sed -E 's/Localization\.//' | sort -u)
    orphan=0
    while IFS= read -r k; do
      [ -z "$k" ] && continue
      # Skip the accessor names themselves.
      case "$k" in localized|self) continue;; esac
      grep -qF "\"$k\"" "$CATALOG" || { echo "FAIL:ORPHAN_LOC_KEY=$k"; orphan=$((orphan+1)); fail_count=$((fail_count+1)); }
    done <<< "$used"
    [ "$orphan" -eq 0 ] && emit_ok LOC_KEYS_RESOLVED
  fi
fi

############################
# B. Layout / project skeleton
############################
empty_dirs=$(find . -mindepth 1 \( -name .locofy -o -name .git \) -prune -o \
  -type d -empty -print 2>/dev/null | sed 's#^\./##' | sort | tr '\n' ',' | sed 's/,$//')
if [ -z "$empty_dirs" ]; then emit_ok NO_EMPTY_FOLDERS; else emit_fail "EMPTY_FOLDERS=$empty_dirs"; fi

if [ -d Features ]; then emit_ok FEATURES_DIR; else emit_fail FEATURES_DIR_MISSING; fi

legacy_flat_dirs=0
for d in Views Components; do
  if [ -d "$d" ]; then
    emit_fail "LEGACY_FLAT_${d}_DIR_PRESENT"
    legacy_flat_dirs=$((legacy_flat_dirs+1))
  fi
done
[ "$legacy_flat_dirs" -eq 0 ] && emit_ok LEGACY_FLAT_DIRS_REMOVED

if [ -d Features ]; then
  while IFS= read -r d; do
    [ -z "$d" ] && continue
    [ -d "$d/Models" ] || emit_warn "MODELS_DIR_MISSING=$d"
  done < <(find Features -mindepth 1 -maxdepth 1 -type d 2>/dev/null | sort)
fi

feature_component_dirs=$(find Features -mindepth 2 -maxdepth 2 -type d -name Components 2>/dev/null | sort)
if [ -z "$feature_component_dirs" ]; then
  emit_ok NO_FEATURE_COMPONENT_DIRS
else
  while IFS= read -r d; do
    [ -z "$d" ] && continue
    emit_fail "FEATURE_COMPONENT_DIR=$d keep_non_figma_ui_inline"
  done <<< "$feature_component_dirs"
fi

invalid_ui_component_files=""
while IFS= read -r component_file; do
  [ -z "$component_file" ] && continue
  if ! has_pascal_case_component_path "$component_file"; then
    invalid_ui_component_files="${invalid_ui_component_files}${invalid_ui_component_files:+,}${component_file#./}"
  fi
done < <(find UIComponents -type f -name '*.swift' 2>/dev/null | sort)
if [ -z "$invalid_ui_component_files" ]; then
  emit_ok UI_COMPONENT_FOLDER_STRUCTURE
else
  emit_fail "UI_COMPONENT_FOLDER_STRUCTURE=$invalid_ui_component_files expected=UIComponents/<PascalCaseComponentName>/<File>.swift"
fi

invalid_navigation_component_files=""
while IFS= read -r navigation_component_file; do
  [ -z "$navigation_component_file" ] && continue
  case "$(basename "$navigation_component_file")" in
    BottomNavigation*View.swift|BottomNav*View.swift|AppTopBar*View.swift|TopAppBar*View.swift|TabBar*View.swift|TabItem*View.swift)
      if ! has_navigation_component_path "$navigation_component_file"; then
        invalid_navigation_component_files="${invalid_navigation_component_files}${invalid_navigation_component_files:+,}${navigation_component_file#./}"
      fi
      ;;
  esac
done < <(swift_sources)
if [ -z "$invalid_navigation_component_files" ]; then
  emit_ok NAV_COMPONENT_FOLDER_STRUCTURE
else
  emit_fail "NAV_COMPONENT_FOLDER_STRUCTURE=$invalid_navigation_component_files expected=UIComponents/<PascalCaseComponentName>/<File>.swift"
fi

# RootTabView required when any merged screen carries tab-bar UI.
tabhits=$(grep -rcE 'TabView|tabItem|BottomTab|BottomNavigationView' Features Views UIComponents 2>/dev/null | awk -F: '{s+=$2} END{print s+0}')
if [ "$tabhits" -gt 0 ]; then
  if [ -f RootTabView.swift ]; then emit_ok ROOTTABVIEW; else emit_fail ROOTTABVIEW_MISSING; fi
fi

bottom_nav_hits=$(grep -rcE 'BottomNavigationView' Features Views UIComponents RootTabView.swift 2>/dev/null | awk -F: '{s+=$2} END{print s+0}')
if [ "$bottom_nav_hits" -gt 0 ]; then
  if [ -f UIComponents/BottomNavigation/BottomNavigationView.swift ]; then
    emit_ok BOTTOM_NAV_COMPONENT
  else
    emit_fail "BOTTOM_NAV_COMPONENT_MISSING=UIComponents/BottomNavigation/BottomNavigationView.swift"
  fi
fi
if [ -f RootTabView.swift ] && [ "$bottom_nav_hits" -gt 0 ]; then
  root_tab_binding_viol=0
  if grep -qE 'BottomNavigationView' RootTabView.swift; then
    :
  else
    echo "FAIL:ROOT_TAB_BINDING_BOTTOM_NAV_NOT_IN_ROOT"; root_tab_binding_viol=$((root_tab_binding_viol+1)); fail_count=$((fail_count+1))
  fi
  feature_bottom_nav=$(grep -rnE 'BottomNavigationView' Features/*/Views Views 2>/dev/null | grep -v 'RootTabView.swift' | wc -l | tr -d ' ')
  if [ "$feature_bottom_nav" -gt 0 ]; then
    echo "FAIL:ROOT_TAB_BINDING_BOTTOM_NAV_IN_SCREEN count=$feature_bottom_nav"; root_tab_binding_viol=$((root_tab_binding_viol+1)); fail_count=$((fail_count+1))
  fi
  bottom_nav_files=UIComponents/BottomNavigation/BottomNavigationView.swift
  if [ -n "$bottom_nav_files" ] && grep -qsE '@Binding[[:space:]]+var[[:space:]]+selectedTab|let[[:space:]]+on[A-Z][A-Za-z0-9_]*Selected[[:space:]]*:' $bottom_nav_files RootTabView.swift 2>/dev/null; then
    :
  else
    echo "FAIL:ROOT_TAB_BINDING_NO_SELECTED_TAB_STATE"; root_tab_binding_viol=$((root_tab_binding_viol+1)); fail_count=$((fail_count+1))
  fi
  if grep -qsE '"Selected"|"Default"' $bottom_nav_files RootTabView.swift 2>/dev/null && ! grep -qsE '@State[[:space:]]+(private[[:space:]]+)?var[[:space:]]+selectedTab|@Binding[[:space:]]+var[[:space:]]+selectedTab|on[A-Z][A-Za-z0-9_]*Selected' RootTabView.swift $bottom_nav_files 2>/dev/null; then
    echo "FAIL:ROOT_TAB_BINDING_HARDCODED_SELECTED_DEFAULT"; root_tab_binding_viol=$((root_tab_binding_viol+1)); fail_count=$((fail_count+1))
  fi
  [ "$root_tab_binding_viol" -eq 0 ] && emit_ok ROOT_TAB_BINDING
fi

for f in AppConstants.swift AccessibilityIdentifiers.swift; do
  if [ -f "$f" ]; then emit_ok "ROOT_$f"; else emit_fail "ROOT_${f}_MISSING"; fi
done

############################
# C. DesignSystem artifact existence
############################
for f in DesignTokens AppFonts IconNames ColorNames AccessibilityCommon; do
  if [ -f "DesignSystem/$f.swift" ]; then emit_ok "DS_$f"; else emit_fail "DS_${f}_MISSING"; fi
done

if [ -f Colors.xcassets/Contents.json ]; then emit_ok XCASSETS_MANIFEST; else emit_fail XCASSETS_MANIFEST_MISSING; fi

############################
# D. Raw literal scan in view code
############################
raw_dim=$(grep -rcE '\.padding\([0-9]|\.frame\([^)]*(width|height):\s*[0-9]|cornerRadius:\s*[0-9]|lineWidth:\s*[0-9]' Features Views UIComponents 2>/dev/null | awk -F: '{s+=$2} END{print s+0}')
if [ "$raw_dim" -eq 0 ]; then emit_ok RAW_DIMENSIONS; else
  emit_fail "RAW_DIMENSIONS=$raw_dim"
  grep -rnE '\.padding\([0-9]|\.frame\([^)]*(width|height):\s*[0-9]' Features Views UIComponents 2>/dev/null | head -8
fi

raw_color=$(grep -rcE 'Color\("[^"]|Color\(red:|Color\(0x|Color\.(white|black|gray|clear|red|blue|green|yellow|orange|pink|purple)' Features Views UIComponents 2>/dev/null | awk -F: '{s+=$2} END{print s+0}')
if [ "$raw_color" -eq 0 ]; then emit_ok RAW_COLORS; else
  emit_fail "RAW_COLORS=$raw_color"
  grep -rnE 'Color\("[^"]|Color\.(white|black|clear)' Features Views UIComponents 2>/dev/null | head -5
fi

raw_img=$(grep -rcE 'Image\("[^"]|Image\(systemName:' Features Views UIComponents 2>/dev/null | awk -F: '{s+=$2} END{print s+0}')
if [ "$raw_img" -eq 0 ]; then emit_ok RAW_IMAGES; else emit_fail "RAW_IMAGES=$raw_img"; fi

sys_font=$(grep -rcE '\.font\(\.system\(size:' Features Views UIComponents 2>/dev/null | awk -F: '{s+=$2} END{print s+0}')
if [ "$sys_font" -eq 0 ]; then emit_ok NO_SYSTEM_FONT; else emit_fail "SYSTEM_FONT=$sys_font"; fi

custom_norel=$(grep -rnE '\.font\(\.custom\([^)]*size:[^)]*\)\)' Features Views UIComponents 2>/dev/null | grep -cv 'relativeTo')
if [ "$custom_norel" -eq 0 ]; then emit_ok CUSTOM_FONT_RELATIVETO; else emit_fail "CUSTOM_FONT_NO_RELATIVETO=$custom_norel"; fi

############################
# E. Deprecated APIs
############################
dep_corner=$(grep -rcE '\.cornerRadius\(' Features Views UIComponents 2>/dev/null | awk -F: '{s+=$2} END{print s+0}')
if [ "$dep_corner" -eq 0 ]; then emit_ok NO_DEPRECATED_CORNERRADIUS; else emit_fail "DEPRECATED_CORNERRADIUS=$dep_corner"; fi

dep_edges=$(grep -rcE '\.edgesIgnoringSafeArea' Features Views UIComponents 2>/dev/null | awk -F: '{s+=$2} END{print s+0}')
if [ "$dep_edges" -eq 0 ]; then emit_ok NO_EDGESIGNORINGSAFEAREA; else emit_fail "DEPRECATED_EDGESIGNORING=$dep_edges"; fi

############################
# F. ViewModel observation
############################
vm_legacy=$(grep -rcE 'ObservableObject|@Published|@StateObject|@ObservedObject' Features 2>/dev/null | awk -F: '{s+=$2} END{print s+0}')
if [ "$vm_legacy" -eq 0 ]; then emit_ok VM_OBSERVABLE; else emit_fail "VM_LEGACY_OBSERVATION=$vm_legacy"; fi

vm_exists_viol=0
vm_ownership_viol=0
if [ -d Features ]; then
  while IFS= read -r view; do
    [ -z "$view" ] && continue
    feature=$(feature_name_from_view "$view")
    vm_files=$(find "Features/$feature/ViewModels" -maxdepth 1 -name '*ViewModel.swift' 2>/dev/null)
    if [ -z "$vm_files" ]; then
      if is_placeholder_view "$view"; then
        emit_warn "PLACEHOLDER_FEATURE_NO_VM=$view"
      else
        echo "FAIL:VIEWMODEL_EXISTS_MISSING=$view"; vm_exists_viol=$((vm_exists_viol+1)); fail_count=$((fail_count+1))
      fi
    fi

    if is_placeholder_view "$view"; then
      continue
    fi

    if grep -qE '@State[[:space:]]+private[[:space:]]+var[[:space:]]+viewModel[[:space:]]*=[[:space:]]*[A-Za-z0-9_]+ViewModel\(' "$view"; then
      :
    else
      echo "FAIL:VIEW_OWNS_VIEWMODEL=$view"; vm_ownership_viol=$((vm_ownership_viol+1)); fail_count=$((fail_count+1))
    fi
  done < <(find Features -path '*/Views/*View.swift' 2>/dev/null | sort)

  while IFS= read -r vm; do
    [ -z "$vm" ] && continue
    grep -qE '@Observable' "$vm" || { echo "FAIL:VIEWMODEL_EXISTS_NO_OBSERVABLE=$vm"; vm_exists_viol=$((vm_exists_viol+1)); fail_count=$((fail_count+1)); }
    grep -qE '@MainActor' "$vm" || { echo "FAIL:VIEWMODEL_EXISTS_NO_MAINACTOR=$vm"; vm_exists_viol=$((vm_exists_viol+1)); fail_count=$((fail_count+1)); }
    if grep -qE 'ObservableObject|@Published|@StateObject|@ObservedObject' "$vm"; then
      echo "FAIL:VIEWMODEL_EXISTS_LEGACY_OBSERVATION=$vm"; vm_exists_viol=$((vm_exists_viol+1)); fail_count=$((fail_count+1))
    fi
  done < <(find Features -path '*/ViewModels/*ViewModel.swift' 2>/dev/null | sort)
fi
[ "$vm_exists_viol" -eq 0 ] && emit_ok VIEWMODEL_EXISTS
[ "$vm_ownership_viol" -eq 0 ] && emit_ok VIEW_OWNS_VIEWMODEL

############################
# G. Model purity (inline + asset-string + UI-key bans)
############################
inline_struct=$(grep -rcE 'private struct [A-Z][A-Za-z]*: Identifiable' Features Views 2>/dev/null | awk -F: '{s+=$2} END{print s+0}')
if [ "$inline_struct" -eq 0 ]; then emit_ok INLINE_STRUCT_MODELS; else emit_fail "INLINE_STRUCT_MODELS=$inline_struct"; fi

tuple_asset=$(grep -rcE 'let [a-zA-Z]+:\s*\[\(\s*(icon|imageName|assetName|image)\s*:\s*String' Features Views 2>/dev/null | awk -F: '{s+=$2} END{print s+0}')
if [ "$tuple_asset" -eq 0 ]; then emit_ok INLINE_TUPLE_MODELS; else emit_fail "INLINE_TUPLE_MODELS=$tuple_asset"; fi

icon_str=$(grep -rcE '\b(iconName|imageName|assetName|trailingIcon|leadingIcon|iconType|iconWidth|iconHeight):\s*String' UIComponents 2>/dev/null | awk -F: '{s+=$2} END{print s+0}')
icon_route_str=$(grep -rcE '\b(type|style|theme):\s*String[^/]*(//.*(icon|image)|=.*(icon|image)|[A-Za-z0-9_]*(Icon|Image))' UIComponents 2>/dev/null | awk -F: '{s+=$2} END{print s+0}')
variant_str=$(grep -rcE '\b(type|rightButtonStyle|style|theme):\s*String' UIComponents 2>/dev/null | awk -F: '{s+=$2} END{print s+0}')
string_icon_fail=$((icon_str + icon_route_str))
string_variant_warn=$((variant_str - icon_route_str))
if [ "$string_variant_warn" -lt 0 ]; then string_variant_warn=0; fi
if [ "$string_icon_fail" -eq 0 ]; then emit_ok STRINGLY_ICON_PROPS; else
  emit_fail "STRINGLY_ICON_PROPS=$string_icon_fail"
  grep -rnE '\b(iconName|imageName|assetName|trailingIcon|leadingIcon|iconType|iconWidth|iconHeight):\s*String|\b(type|style|theme):\s*String[^/]*(//.*(icon|image)|=.*(icon|image)|[A-Za-z0-9_]*(Icon|Image))' UIComponents 2>/dev/null | head -8
fi
[ "$string_icon_fail" -eq 0 ] && emit_ok STRING_ICON_PARAMS
[ "$string_variant_warn" -eq 0 ] || emit_warn "STRINGLY_VARIANT_PROPS=$string_variant_warn"

mod_ui=$(grep -rcE '(Localization|LocalizationKeys|IconNames|AccessibilityIdentifiers)\.' Features/*/Models 2>/dev/null | awk -F: '{s+=$2} END{print s+0}')
if [ "$mod_ui" -eq 0 ]; then emit_ok MODEL_NO_UI_KEYS; else emit_fail "MODEL_UI_KEYS=$mod_ui"; fi

mod_asset=$(grep -rcE '\b(iconName|imageName|assetName|bgImage|logoName):\s*String' Features/*/Models 2>/dev/null | awk -F: '{s+=$2} END{print s+0}')
if [ "$mod_asset" -eq 0 ]; then emit_ok MODEL_NO_ASSET_STRING; else emit_fail "MODEL_ASSET_STRING=$mod_asset"; fi

############################
# H. Accessibility — raw modifier outside utility
############################
raw_a11y=$(grep -rnE '\.accessibility(Identifier|Label|Hint)\(' Features Views UIComponents 2>/dev/null | grep -v 'AccessibilityCommon.swift' | wc -l | tr -d ' ')
if [ "$raw_a11y" -eq 0 ]; then emit_ok NO_RAW_A11Y_OUTSIDE_UTILITY; else
  emit_fail "RAW_A11Y_OUTSIDE_UTILITY=$raw_a11y"
  grep -rnE '\.accessibility(Identifier|Label|Hint)\(' Features Views UIComponents 2>/dev/null | grep -v 'AccessibilityCommon.swift' | head -8
fi

############################
# H2. AccessibilityCommon shape — full signature required
############################
A11Y_FILE=DesignSystem/AccessibilityCommon.swift
if [ -f "$A11Y_FILE" ]; then
  missing_field=0
  for kw in 'var suffix:' 'var value:' 'var addTraits:' 'var removeTraits:' 'var accessibilityElement:' 'enum AccessibilityElement' 'struct AccessibilityTraitConfiguration' 'func applyIf'; do
    grep -q "$kw" "$A11Y_FILE" || { echo "FAIL:A11Y_COMMON_SHAPE_MISSING=$kw"; missing_field=$((missing_field+1)); fail_count=$((fail_count+1)); }
  done
  [ "$missing_field" -eq 0 ] && emit_ok A11Y_COMMON_SHAPE
fi

############################
# H2b. AccessibilityCommon type name == file name (user feedback)
#      The `: ViewModifier` struct in AccessibilityCommon.swift MUST be named
#      `AccessibilityCommon` (filename == primary type name). The historical
#      `struct AccessibilityModifier` mismatch is a FAIL.
############################
if [ -f "$A11Y_FILE" ]; then
  if grep -qE '^[[:space:]]*(public[[:space:]]+|internal[[:space:]]+)?struct[[:space:]]+AccessibilityCommon[[:space:]]*:[[:space:]]*ViewModifier\b' "$A11Y_FILE"; then
    emit_ok A11Y_COMMON_TYPENAME
  else
    vm_name=$(grep -nE 'struct[[:space:]]+[A-Za-z0-9_]+[[:space:]]*:[[:space:]]*ViewModifier\b' "$A11Y_FILE" 2>/dev/null | head -1)
    emit_fail "A11Y_COMMON_TYPENAME=${vm_name:-no_viewmodifier_struct}"
  fi
fi

############################
# H2c. Screen/support View suffix and reusable-component file/type agreement.
############################
view_suffix_viol=0
while IFS= read -r line; do
  [ -z "$line" ] && continue
  sname=$(echo "$line" | sed -E 's/.*struct[[:space:]]+([A-Za-z0-9_]+).*/\1/')
  case "$sname" in
    *View|*_Previews) ;;
    *) echo "FAIL:VIEW_SUFFIX=$line"; view_suffix_viol=$((view_suffix_viol+1)); fail_count=$((fail_count+1));;
  esac
done < <(grep -rnE '^[[:space:]]*(public[[:space:]]+|internal[[:space:]]+|private[[:space:]]+|fileprivate[[:space:]]+)?struct[[:space:]]+[A-Za-z0-9_]+[[:space:]]*:[^{]*\bView\b' Features Views 2>/dev/null | grep -vE '\bViewModifier\b|\bViewBuilder\b')
[ "$view_suffix_viol" -eq 0 ] && emit_ok VIEW_SUFFIX

component_name_viol=0
while IFS= read -r component_file; do
  [ -z "$component_file" ] && continue
  component_base=$(basename "$component_file" .swift)
  if ! grep -qE "^[[:space:]]*(public[[:space:]]+|internal[[:space:]]+)?struct[[:space:]]+$component_base[[:space:]]*:[^{]*\\bView\\b" "$component_file" 2>/dev/null; then
    emit_fail "COMPONENT_FILE_TYPE=$component_file expected=$component_base"
    component_name_viol=$((component_name_viol+1))
  fi
done < <(find UIComponents -type f -name '*.swift' 2>/dev/null | sort)
[ "$component_name_viol" -eq 0 ] && emit_ok COMPONENT_FILE_TYPE

unused_components=0
while IFS= read -r decl; do
  [ -z "$decl" ] && continue
  f=${decl%%:*}
  sname=$(echo "$decl" | sed -E 's/.*struct[[:space:]]+([A-Za-z0-9_]+View).*/\1/')
  refs=$(production_ref_count "$sname" "$f")
  if [ "$refs" -eq 0 ]; then
    echo "FAIL:UNUSED_COMPONENTS=$sname file=$f"; unused_components=$((unused_components+1)); fail_count=$((fail_count+1))
  fi
done < <(grep -rnE '^[[:space:]]*(public[[:space:]]+|internal[[:space:]]+|private[[:space:]]+|fileprivate[[:space:]]+)?struct[[:space:]]+[A-Za-z0-9_]+View[[:space:]]*:[^{]*\bView\b' UIComponents 2>/dev/null | grep -vE '\bViewModifier\b|\bViewBuilder\b')
[ "$unused_components" -eq 0 ] && emit_ok UNUSED_COMPONENTS

############################
# H2d. Generated Figma components — normalized and consolidated.
# The normalized key groups raw declarations; a new SwiftUI canonical is `<Key>View`.
############################
if [ -z "$GENERATED_GROUPS" ]; then
  emit_fail GENERATED_COMPONENT_GROUPS_MISSING
else
  group_count=0
  group_violations=0

  while IFS=$'\t' read -r raw_cell normalized_key existing_cell canonical_cell; do
    [ -z "$raw_cell" ] && continue
    group_count=$((group_count+1))
    canonical=$(canonical_type_from_cell "$canonical_cell")
    canonical_path=$(canonical_path_from_cell "$canonical_cell")
    if [ -z "$canonical" ] || [ -z "$canonical_path" ] || [ "$canonical" = "$canonical_path" ]; then
      emit_fail "GENERATED_COMPONENT_GROUP_INVALID=key=$normalized_key canonical=$canonical_cell"
      group_violations=$((group_violations+1))
      continue
    fi
    case "$existing_cell" in
      ""|none|None|NONE|-|—)
        expected="${normalized_key}View"
        if [ "$canonical" != "$expected" ]; then
          emit_fail "GENERATED_COMPONENT_CANONICAL=key=$normalized_key expected=$expected actual=$canonical"
          group_violations=$((group_violations+1))
        fi
        if ! has_pascal_case_component_path "$canonical_path"; then
          emit_fail "GENERATED_COMPONENT_LOCATION=$canonical path=$canonical_path expected=UIComponents/<PascalCaseComponentName>/<File>.swift"
          group_violations=$((group_violations+1))
        fi
        ;;
    esac

    canonical_file=$(resolve_generated_canonical_file "$canonical_path")
    if [ -z "$canonical_file" ] || [ ! -f "$canonical_file" ]; then
      emit_fail "GENERATED_COMPONENT_FILE_MISSING=$canonical path=$canonical_path"
      group_violations=$((group_violations+1))
    else
      definition_count=0
      while IFS= read -r source_file; do
        [ -z "$source_file" ] && continue
        matches=$(grep -Ec "^[[:space:]]*(public[[:space:]]+|internal[[:space:]]+|private[[:space:]]+|fileprivate[[:space:]]+)?struct[[:space:]]+$canonical[[:space:]]*:[^{]*\\bView\\b" "$source_file" 2>/dev/null)
        definition_count=$((definition_count+matches))
      done < <(swift_sources)
      if [ "$definition_count" -ne 1 ]; then
        emit_fail "GENERATED_COMPONENT_CANONICAL_COUNT=$canonical count=$definition_count"
        group_violations=$((group_violations+1))
      fi

      canonical_file=${canonical_file#./}
      refs=$(production_ref_count "$canonical" "$canonical_file")
      if [ "$refs" -eq 0 ]; then
        emit_fail "GENERATED_COMPONENT_CALLERS=$canonical production_refs=0"
        group_violations=$((group_violations+1))
      fi
    fi

    while IFS= read -r raw_name; do
      [ -z "$raw_name" ] && continue
      raw_base="$raw_name"
      case "$raw_base" in *View) raw_base=${raw_base%View};; esac
      raw_base=$(printf '%s\n' "$raw_base" | sed -E 's/[0-9]+$//')
      case "$raw_base" in *View) raw_base=${raw_base%View};; esac
      if [ "$raw_base" != "$normalized_key" ]; then
        emit_fail "GENERATED_COMPONENT_GROUP_KEY=$raw_name expected_key=$raw_base actual_key=$normalized_key"
        group_violations=$((group_violations+1))
      fi
      [ "$raw_name" = "$canonical" ] && continue

      residual_refs=0
      while IFS= read -r source_file; do
        [ -z "$source_file" ] && continue
        matches=$(grep -Ec "\\b$raw_name\\b" "$source_file" 2>/dev/null)
        residual_refs=$((residual_refs+matches))
      done < <(swift_sources)
      residual_file=$(find UIComponents Features Views -type f -name "$raw_name.swift" 2>/dev/null | head -1)
      if [ "$residual_refs" -gt 0 ] || [ -n "$residual_file" ]; then
        emit_fail "GENERATED_COMPONENT_RESIDUAL=$raw_name refs=$residual_refs file=${residual_file:-none}"
        group_violations=$((group_violations+1))
      fi
    done < <(printf '%s\n' "$raw_cell" | tr ',' '\n' \
      | sed -E 's/^[[:space:]]*([A-Za-z_][A-Za-z0-9_]*).*/\1/' \
      | grep -E '^[A-Za-z_][A-Za-z0-9_]*$')
  done < <(generated_group_rows)

  [ "$group_violations" -eq 0 ] && emit_ok "GENERATED_COMPONENT_GROUPS groups=$group_count"
fi

if [ -n "$GENERATED_GROUPS" ]; then
  if [ ! -f "$EXPECTED_FIGMA_PROBE" ]; then
    emit_fail "EXPECTED_FIGMA_PROBE_MISSING=$EXPECTED_FIGMA_PROBE"
  else
    EXPECTED_FIGMA_COMMAND=()
    command -v node >/dev/null 2>&1 && EXPECTED_FIGMA_COMMAND=(node)
    if [ "${#EXPECTED_FIGMA_COMMAND[@]}" -eq 0 ]; then
      emit_fail "EXPECTED_FIGMA_NODE_MISSING=node"
    else
      expected_args=(
        --framework swiftui
        --project-root "$PWD"
        --groups "$GENERATED_GROUPS"
      )
      expected_output=$("${EXPECTED_FIGMA_COMMAND[@]}" "$EXPECTED_FIGMA_PROBE" "${expected_args[@]}" 2>&1)
      expected_status=$?
      printf '%s\n' "$expected_output"
      expected_failures=$(printf '%s\n' "$expected_output" | grep -c '^FAIL:')
      fail_count=$((fail_count+expected_failures))
      if [ "$expected_status" -ne 0 ] && [ "$expected_failures" -eq 0 ]; then
        emit_fail "EXPECTED_FIGMA_PROBE_EXIT=$expected_status"
      fi
    fi
  fi
fi

############################
# H3. Raw NSLocalizedString in views — BANNED everywhere except the Localization
#     enum extension. Views call `.localized`; the enum's `var localized`/`func
#     localized(_:)` is the ONLY place `NSLocalizedString(` belongs. A direct call
#     in a view/component bypasses the canonical accessor.
############################
nsl=$(grep -rcE 'NSLocalizedString\(' Features Views UIComponents DesignSystem/AccessibilityCommon.swift 2>/dev/null | awk -F: '{s+=$2} END{print s+0}')
if [ "$nsl" -eq 0 ]; then emit_ok NO_RAW_NSLOCALIZEDSTRING_IN_VIEWS; else
  emit_fail "RAW_NSLOCALIZEDSTRING_IN_VIEWS=$nsl"
  grep -rnE 'NSLocalizedString\(' Features Views UIComponents DesignSystem/AccessibilityCommon.swift 2>/dev/null | head -5
fi

############################
# H4. One model type per file + Model suffix on files and types
############################
model_violations=0
while IFS= read -r f; do
  base=$(basename "$f" .swift)
  declaration_count=$(grep -cE '^((public|internal|package|private|fileprivate|open|final|indirect)[[:space:]]+)*(struct|class|enum|protocol|actor)[[:space:]]+[A-Za-z0-9_]+' "$f" 2>/dev/null)
  if [ "$declaration_count" -ne 1 ]; then
    echo "FAIL:MODEL_FILE_TYPE_COUNT=$f count=$declaration_count expected=1"; model_violations=$((model_violations+1)); fail_count=$((fail_count+1))
  fi
  # Filename must end in Model
  if ! echo "$base" | grep -qE 'Model$'; then
    echo "FAIL:MODEL_SUFFIX_FILENAME=$f"; model_violations=$((model_violations+1)); fail_count=$((fail_count+1))
    continue
  fi
  # Primary type declared inside must also end in Model
  if ! grep -qE "^((public|internal|package|private|fileprivate|open|final|indirect)[[:space:]]+)*(struct|class|enum)[[:space:]]+[A-Za-z0-9_]+Model\b" "$f"; then
    echo "FAIL:MODEL_SUFFIX_TYPE=$f"; model_violations=$((model_violations+1)); fail_count=$((fail_count+1))
  fi
done < <({ find Features -path '*/Models/*.swift' 2>/dev/null; find Models -name '*.swift' 2>/dev/null; })
[ "$model_violations" -eq 0 ] && { emit_ok MODEL_FILE_STRUCTURE; emit_ok MODEL_SUFFIX; }

############################
# H6. Fixed-size Spacer banned
############################
fixed_spacer=$(grep -rnE 'Spacer\(\)\s*\.frame\(\s*(width|height)\s*:' Features Views UIComponents 2>/dev/null | wc -l | tr -d ' ')
if [ "$fixed_spacer" -eq 0 ]; then emit_ok NO_FIXED_SPACER; else
  emit_fail "FIXED_SPACER=$fixed_spacer"
  grep -rnE 'Spacer\(\)\s*\.frame\(\s*(width|height)\s*:' Features Views UIComponents 2>/dev/null | head -5
fi

############################
# H7. No `// TODO:` deferment of HARD GATE rules in written code
############################
todo_defer=$(grep -rnE '//\s*TODO:.*([Ll]ocali[sz]e|[Aa]ccessibilit|[Cc]olor|[Ii]con|[Tt]oken)' Features Views UIComponents DesignSystem 2>/dev/null | wc -l | tr -d ' ')
if [ "$todo_defer" -eq 0 ]; then emit_ok NO_TODO_DEFERMENT; else
  emit_fail "TODO_DEFERMENT=$todo_defer"
  grep -rnE '//\s*TODO:.*([Ll]ocali[sz]e|[Aa]ccessibilit|[Cc]olor|[Ii]con|[Tt]oken)' Features Views UIComponents DesignSystem 2>/dev/null | head -5
fi

############################
# I. Preview annotation per screen
############################
missing_prev=0
while IFS= read -r f; do
  grep -q -E '#Preview|PreviewProvider' "$f" || { echo "FAIL:PREVIEW_MISSING=$f"; missing_prev=$((missing_prev+1)); fail_count=$((fail_count+1)); }
done < <(find Features -path '*/Views/*.swift' 2>/dev/null)
if [ "$missing_prev" -eq 0 ]; then emit_ok PREVIEW_ALL_SCREENS; fi

############################
# J. Figma variable names kept verbatim (never renamed / stripped)
############################
# A DesignTokens value with a `// Figma variable` comment directly above it is a
# named Figma design variable — its name AND the comment must survive enhancement.
# The trigger is the INCOMING generated marker, NOT the enhanced output, so the
# check cannot be bypassed by deleting every comment during the rename (which would
# otherwise make a naive output-only probe see 0 comments and skip).
#
# Enhanced DesignTokens (exclude the incoming generated copy kept under .locofy).
DT=$(find . -name 'DesignTokens.swift' -not -path '*/.locofy/*' 2>/dev/null | head -1)
# Incoming generated DesignTokens (present under .locofy during the run, before cleanup).
GEN=$(find . .. ../.. -path '*generated*' -name 'DesignTokens.swift' 2>/dev/null | head -1)

# Extract each token name that carries a `// Figma variable` comment directly above it.
fig_extract() {
  awk '
    /\/\/[[:space:]]*Figma variable/ { pending=1; next }
    pending==1 && NF==0 { next }
    pending==1 {
      if (match($0, /[[:space:]](let|var)[[:space:]]+[A-Za-z_][A-Za-z0-9_]*/)) {
        n=substr($0, RSTART, RLENGTH); gsub(/.*[[:space:]]/, "", n); print n
      }
      pending=0
    }
  ' "$1" 2>/dev/null | sort -u
}

if [ -n "$GEN" ] && grep -q '// Figma variable' "$GEN" 2>/dev/null; then
  # Incoming HAS Figma variables → every name + the comment marker MUST be preserved.
  if [ -z "$DT" ]; then
    emit_fail FIGMA_VARIABLE_DESIGNTOKENS_MISSING
  else
    fig_missing=0
    while IFS= read -r n; do
      [ -z "$n" ] && continue
      grep -qE "(let|var)[[:space:]]+$n\b" "$DT" || { echo "FAIL:FIGMA_VARIABLE_RENAMED=$n"; fig_missing=$((fig_missing+1)); fail_count=$((fail_count+1)); }
    done <<< "$(fig_extract "$GEN")"
    if ! grep -q '// Figma variable' "$DT" 2>/dev/null; then
      echo "FAIL:FIGMA_VARIABLE_COMMENT_STRIPPED"; fig_missing=$((fig_missing+1)); fail_count=$((fail_count+1))
    fi
    [ "$fig_missing" -eq 0 ] && emit_ok FIGMA_VARIABLE_NAMES
  fi
elif [ -n "$DT" ] && grep -q '// Figma variable' "$DT" 2>/dev/null; then
  # No incoming reference, but the enhanced file has Figma comments — structural
  # check: each comment sits directly above a token declaration (not orphaned).
  fig_orphan=$(awk '
    /\/\/[[:space:]]*Figma variable/ { pending=1; next }
    pending==1 && NF==0 { next }
    pending==1 { if ($0 !~ /(static |let |var )/) print NR; pending=0 }
  ' "$DT" | wc -l | tr -d ' ')
  if [ "$fig_orphan" -eq 0 ]; then emit_ok FIGMA_VARIABLE_NAMES; else
    emit_fail "FIGMA_VARIABLE_ORPHANED=$fig_orphan"
    grep -nB1 '// Figma variable' "$DT" 2>/dev/null | head -10
  fi
fi

############################
# J2. Component prop / state names kept verbatim (never renamed / stripped)
############################
# A declaration whose line directly above carries a `// Component prop`,
# `// Component state`, or `// Component prop & state` comment is an intentional
# named prop/state binding from the design — its identifier MUST survive
# enhancement (same mandate as `// Figma variable`, HARD GATE 10). Trigger is the
# INCOMING generated marker, NOT the enhanced output, so the check cannot be
# bypassed by deleting the comments during a rename.
#
# Extract each identifier that carries a Component prop/state comment directly above it.
comp_extract() {
  awk '
    /\/\/[[:space:]]*Component[[:space:]]+(prop|state)/ { pending=1; next }
    pending==1 && NF==0 { next }
    pending==1 {
      if (match($0, /[[:space:]](let|var)[[:space:]]+[A-Za-z_][A-Za-z0-9_]*/)) {
        n=substr($0, RSTART, RLENGTH); gsub(/.*[[:space:]]/, "", n); print n
      }
      pending=0
    }
  ' "$1" 2>/dev/null
}
# Incoming generated Swift sources (present under a generated/.locofy dir during the run).
GEN_SWIFT=$(find . .. ../.. -path '*generated*' -name '*.swift' 2>/dev/null)
comp_names=$(for gf in $GEN_SWIFT; do comp_extract "$gf"; done | sort -u)
if [ -n "$comp_names" ]; then
  # Enhanced sources only — exclude the incoming generated copy so a name isn't
  # "found" in the very file we're guarding against.
  ENH_SWIFT=$(find Features Views UIComponents . -name '*.swift' \
    -not -path '*/.locofy/*' -not -path '*generated*' \
    -not -path '*/DerivedData/*' -not -path '*/build/*' 2>/dev/null | sort -u)
  comp_missing=0
  comp_unused=0
  while IFS= read -r n; do
    [ -z "$n" ] && continue
    if [ -n "$ENH_SWIFT" ] && grep -qsE "(let|var)[[:space:]]+$n\b" $ENH_SWIFT 2>/dev/null; then
      occurrences=$(awk -v name="$n" '{ line=$0; gsub(/[^A-Za-z0-9_]/, " ", line); count=split(line, parts, / +/); for (i=1; i<=count; i++) if (parts[i] == name) hits++ } END { print hits+0 }' $ENH_SWIFT)
      if [ "$occurrences" -lt 2 ]; then
        echo "FAIL:COMPONENT_PROP_UNUSED=$n"; comp_unused=$((comp_unused+1)); fail_count=$((fail_count+1))
      fi
    else
      echo "FAIL:COMPONENT_PROP_RENAMED=$n"; comp_missing=$((comp_missing+1)); fail_count=$((fail_count+1))
    fi
  done <<< "$comp_names"
  [ "$comp_missing" -eq 0 ] && emit_ok COMPONENT_PROP_NAMES
  [ "$comp_unused" -eq 0 ] && emit_ok COMPONENT_PROP_USAGE
fi

############################
# H3. FONT_REGISTERED — bundled custom fonts must be REGISTERED or
#     `.font(.custom(...))` silently renders as the system font (HARD GATE 9,
#     user feedback). Valid registration: UIAppFonts in a physical Info.plist,
#     OR runtime CTFontManager registration (LocofyFontRegistration) for
#     synthesized-plist targets. Skipped when no fonts are bundled.
############################
FONT_FILES=$(find . -type f \( -iname '*.ttf' -o -iname '*.otf' \) \
  -not -path '*/.locofy/*' -not -path '*/DerivedData/*' -not -path '*/build/*' 2>/dev/null)
if [ -n "$FONT_FILES" ]; then
  font_reg=0
  if grep -rqs --include='Info.plist' --exclude-dir=.locofy --exclude-dir=DerivedData --exclude-dir=build 'UIAppFonts' . 2>/dev/null; then
    font_reg=1
  fi
  if grep -rqsE 'LocofyFontRegistration|CTFontManagerRegisterFontsForURL' --include='*.swift' . 2>/dev/null; then
    font_reg=1
  fi
  if [ "$font_reg" -eq 1 ]; then emit_ok FONT_REGISTERED; else
    emit_fail FONT_REGISTERED
    echo "  bundled fonts unregistered (no UIAppFonts in a physical Info.plist, no runtime CTFontManager registration). Run register-fonts.rb:"
    echo "$FONT_FILES" | head -10
  fi
fi

############################
# Summary
############################
if [ "$fail_count" -eq 0 ]; then
  echo "PROBES_RESULT:ALL_PASS warnings=$warn_count"
  exit 0
else
  echo "PROBES_RESULT:FAIL count=$fail_count warnings=$warn_count"
  exit 1
fi
